189	<script>
190	(function(){
191	  var LAYOUT_KEY = 'coach888_layout';
192	  var TITLES_KEY = 'coach888_titles';
193	  var BADGES_KEY = 'coach888_badges';
194	
195	  function renumber(grid){
196	    grid.querySelectorAll('.item .num').forEach(function(el, i){ el.textContent = i + 1; });
197	    var title = grid.previousElementSibling;
198	    if (title && title.classList.contains('section-title')) {
199	      var countEl = title.querySelector('.count');
200	      if (countEl) countEl.textContent = grid.querySelectorAll('.item').length + '項';
201	    }
202	  }
203	
204	  function saveLayout(){
205	    var layout = {};
206	    document.querySelectorAll('.grid').forEach(function(grid){
207	      layout[grid.dataset.section] = Array.prototype.map.call(grid.querySelectorAll('.item'), function(it){ return it.dataset.url; });
208	    });
209	    localStorage.setItem(LAYOUT_KEY, JSON.stringify(layout));
210	    // 清掉2026-07-20版之前的舊格式（每組各自存一個key），避免新舊格式打架
211	    document.querySelectorAll('.grid').forEach(function(grid){
212	      localStorage.removeItem('coach888_order_' + grid.dataset.section);
213	    });
214	  }
215	
216	  function loadLayout(){
217	    var raw = localStorage.getItem(LAYOUT_KEY);
218	    if (raw) {
219	      try { return JSON.parse(raw); } catch(e){}
220	    }
221	    // 相容舊版：只支援組內排序、每組各自一個key，讀出來當初始佈局
222	    var legacy = {}, found = false;
223	    document.querySelectorAll('.grid').forEach(function(grid){
224	      var old = localStorage.getItem('coach888_order_' + grid.dataset.section);
225	      if (old) {
226	        try { legacy[grid.dataset.section] = JSON.parse(old); found = true; } catch(e){}
227	      }
228	    });
229	    return found ? legacy : null;
230	  }
231	
232	  function saveTitles(){
233	    var titles = {};
234	    document.querySelectorAll('.section-title').forEach(function(t){
235	      var span = t.querySelector('.title-text');
236	      if (span) titles[t.dataset.section] = span.textContent.trim();
237	    });
238	    localStorage.setItem(TITLES_KEY, JSON.stringify(titles));
239	  }
240	
241	  function applyTitles(){
242	    var raw = localStorage.getItem(TITLES_KEY);
243	    if (!raw) return;
244	    try {
245	      var titles = JSON.parse(raw);
246	      document.querySelectorAll('.section-title').forEach(function(t){
247	        var span = t.querySelector('.title-text');
248	        if (span && titles[t.dataset.section] != null) span.textContent = titles[t.dataset.section];
249	      });
250	    } catch(e){}
251	  }
252	
253	  function saveBadges(){
254	    var badges = {};
255	    document.querySelectorAll('.item').forEach(function(it){
256	      var b = it.querySelector('.badge');
257	      if (b) badges[it.dataset.url] = b.textContent.trim();
258	    });
259	    localStorage.setItem(BADGES_KEY, JSON.stringify(badges));
260	  }
261	
262	  function applyBadges(){
263	    var raw = localStorage.getItem(BADGES_KEY);
264	    if (!raw) return;
265	    try {
266	      var badges = JSON.parse(raw);
267	      document.querySelectorAll('.item').forEach(function(it){
268	        var b = it.querySelector('.badge');
269	        if (b && badges[it.dataset.url] != null) b.textContent = badges[it.dataset.url];
270	      });
271	    } catch(e){}
272	  }
273	
274	  function bindEditable(el, onSave){
275	    el.addEventListener('keydown', function(e){
276	      if (e.key === 'Enter') { e.preventDefault(); el.blur(); }
277	    });
278	    el.addEventListener('blur', onSave);
279	  }
280	
281	  function applyLayout(){
282	    var layout = loadLayout();
283	    if (!layout) return;
284	    var allItems = {};
285	    document.querySelectorAll('.item').forEach(function(it){ allItems[it.dataset.url] = it; });
286	    document.querySelectorAll('.grid').forEach(function(grid){
287	      var ids = layout[grid.dataset.section];
288	      if (!ids) return;
289	      ids.forEach(function(id){
290	        if (allItems[id]) grid.appendChild(allItems[id]);
291	      });
292	    });
293	  }
294	
295	  function getDragAfterElement(grid, y){
296	    var els = Array.prototype.slice.call(grid.querySelectorAll('.item:not(.dragging)'));
297	    return els.reduce(function(closest, child){
298	      var box = child.getBoundingClientRect();
299	      var offset = y - box.top - box.height / 2;
300	      if (offset < 0 && offset > closest.offset) {
301	        return { offset: offset, element: child };
302	      }
303	      return closest;
304	    }, { offset: -Infinity, element: null }).element;
305	  }
306	
307	  // 2026-07-20 改用滑鼠事件手刻拖曳（不用 HTML5 原生 draggable API）：
308	  // .item 內部有 <a class="name" href="..."> 連結，瀏覽器對連結元素有自己的
309	  // 原生拖曳行為，跟外層 draggable="true" 互相打架，導致放開時被瀏覽器判定
310	  // 為無效拖放而彈回原位（教練實測回報「都會被打回原來的位置」）。改成監聽
311	  // drag-handle 的 mousedown/mousemove/mouseup 手動搬移 DOM，完全不觸發原生
312	  // 拖放機制，也就不會有這個衝突。
313	  var dragEl = null;
314	  var sourceGrid = null;
315	
316	  function onMouseMove(e){
317	    if (!dragEl) return;
318	    var el = document.elementFromPoint(e.clientX, e.clientY);
319	    var targetGrid = el ? el.closest('.grid') : null;
320	    if (!targetGrid) return;
321	    var afterEl = getDragAfterElement(targetGrid, e.clientY);
322	    if (afterEl == null) {
323	      targetGrid.appendChild(dragEl);
324	    } else if (afterEl !== dragEl) {
325	      targetGrid.insertBefore(dragEl, afterEl);
326	    }
327	  }
328	
329	  function onMouseUp(){
330	    if (!dragEl) return;
331	    dragEl.classList.remove('dragging');
332	    var targetGrid = dragEl.closest('.grid');
333	    renumber(sourceGrid);
334	    if (targetGrid !== sourceGrid) renumber(targetGrid);
335	    saveLayout();
336	    dragEl = null;
337	    sourceGrid = null;
338	    document.removeEventListener('mousemove', onMouseMove);
339	    document.removeEventListener('mouseup', onMouseUp);
340	  }
341	
342	  applyLayout();
343	  applyTitles();
344	  applyBadges();
345	
346	  document.querySelectorAll('.item').forEach(function(item){
347	    var handle = item.querySelector('.drag-handle');
348	    handle.addEventListener('mousedown', function(e){
349	      e.preventDefault();
350	      dragEl = item;
351	      sourceGrid = item.closest('.grid');
352	      item.classList.add('dragging');
353	      document.addEventListener('mousemove', onMouseMove);
354	      document.addEventListener('mouseup', onMouseUp);
355	    });
356	  });
357	
358	  document.querySelectorAll('.title-text').forEach(function(el){ bindEditable(el, saveTitles); });
359	  document.querySelectorAll('.badge').forEach(function(el){ bindEditable(el, saveBadges); });
360	
361	  document.querySelectorAll('.grid').forEach(renumber);
362	
363	  var toastEl = document.getElementById('toast');
364	  function toast(msg){
365	    toastEl.textContent = msg;
366	    toastEl.classList.add('show');
367	    setTimeout(function(){ toastEl.classList.remove('show'); }, 2200);
368	  }
369	
370	  document.getElementById('btnCopy').addEventListener('click', function(){
371	    var lines = [];
372	    document.querySelectorAll('.section-title').forEach(function(title, idx){
373	      var grid = document.querySelectorAll('.grid')[idx];
374	      lines.push(title.textContent.trim());
375	      grid.querySelectorAll('.item').forEach(function(item){
376	        var num = item.querySelector('.num').textContent;
377	        var name = item.querySelector('.name').textContent;
378	        var url = item.dataset.url;
379	        var badge = item.querySelector('.badge').textContent.trim();
380	        lines.push('  ' + num + '. ' + name + '  ' + url + '  [' + badge + ']');
381	      });
382	      lines.push('');
383	    });
384	    var text = lines.join('\n');
385	    navigator.clipboard.writeText(text).then(function(){
386	      toast('已複製目前排序，貼給小龍蝦即可固化進正式檔案');
387	    }, function(){
388	      toast('複製失敗，請手動選取畫面上的文字');
389	    });
390	  });
391	})();
392	</script>
393	</body>
394	</html>
