window.alert = function(msg){ window.__lastAlert = msg; };
window.__remarkResults = window.__remarkResults || [];

window.__extractRows2 = function() {
  const t = document.querySelectorAll('#show_search_result table')[1];
  if (!t) return [];
  return [...t.rows].slice(1).map(r => {
    const cells = [...r.cells];
    const linkCell = cells.find(c => c.querySelector('a[onclick*="search_invoice_detail"]'));
    const a = linkCell ? linkCell.querySelector('a[onclick*="search_invoice_detail"]') : null;
    const onclick = a ? a.getAttribute('onclick') : null;
    const m = onclick ? onclick.match(/search_invoice_detail\('([^']+)'\)/) : null;
    const token = m ? m[1] : null;
    const invno = a ? a.innerText.trim() : null;
    return {invno, token};
  }).filter(x=>x.invno);
};

window.__closeModal = function(){
  const btns = [...document.querySelectorAll('.modal.show .close, .modal.in .close, .modal[style*="display: block"] .close')];
  if (btns.length) { btns[btns.length-1].click(); return true; }
  const anyClose = document.querySelector('.close');
  if (anyClose) { anyClose.click(); return true; }
  return false;
};

window.__queryDateRemarks = async function(dateStr, targetInvNos, meta) {
  const sf = document.querySelector('input[name="StartInvDate"]');
  const ef = document.querySelector('input[name="EndInvDate"]');
  sf.value = dateStr; ef.value = dateStr;
  search_invoice_info.send_search_invoice('1');
  await new Promise(r=>setTimeout(r, 1800));
  const rows = window.__extractRows2();
  const targets = new Set(targetInvNos);
  const matched = rows.filter(r => targets.has(r.invno));
  const out = [];
  for (const r of matched) {
    search_invoice_info.search_invoice_detail(r.token);
    await new Promise(res=>setTimeout(res, 1400));
    const modal = document.querySelector('.modal_div');
    let remark = null, buyerName = null, taxId = null;
    if (modal) {
      const txt = modal.innerText;
      const mm = txt.match(/發票備註\t([^\n]*)/);
      remark = mm ? mm[1].trim() : '';
      const bn = txt.match(/買受人名稱\t([^\t\n]*)/);
      buyerName = bn ? bn[1].trim() : null;
      const ti = txt.match(/買受人統編\t([^\t\n]*)/);
      taxId = ti ? ti[1].trim() : null;
    }
    out.push({invno: r.invno, remark, buyerName, taxId, date: dateStr, metaTid: (meta&&meta[r.invno])||null});
    window.__closeModal();
    await new Promise(res=>setTimeout(res, 400));
  }
  window.__remarkResults = window.__remarkResults.concat(out);
  return {date: dateStr, rowsFound: rows.length, targetsRequested: targetInvNos.length, matched: matched.length, results: out};
};
'setup done';

({
  modalDivCount: document.querySelectorAll('.modal_div').length,
  modalOpenCount: document.querySelectorAll('.modal.show, .modal.in').length,
  allModalDivsText: [...document.querySelectorAll('.modal_div')].map(m=>m.innerText.slice(0,100)),
  rows: window.__extractRows2().slice(0,10)
})

